import { createRoot } from 'react-dom/client';
import { Search, ShieldCheck, Sparkles, Dumbbell, Database, KeyRound, Compass, Swords, Filter, ExternalLink } from 'lucide-react';
import { martialArts, categories, equipmentOptions, externalSources, stats, searchDrills, getArtProfile } from './data/combatData.js';
import './styles.css';

const difficulties = ['beginner', 'intermediate', 'advanced'];
const contactLevels = ['solo', 'no-contact', 'light-contact', 'controlled-contact'];
const formats = ['solo', 'partner'];

function Pill({ children }) { return <span className="pill">{children}</span>; }

function App() {
  const [query, setQuery] = useState('');
  const [martialArt, setMartialArt] = useState('');
  const [category, setCategory] = useState('');
  const [difficulty, setDifficulty] = useState('');
  const [equipment, setEquipment] = useState('');
  const [contactLevel, setContactLevel] = useState('');
  const [format, setFormat] = useState('');
  const [selectedArt, setSelectedArt] = useState('bjj');
  const [selectedDrill, setSelectedDrill] = useState(null);

  const results = useMemo(() => searchDrills({ query, martialArt, category, difficulty, equipment, contactLevel, format }).slice(0, 120), [query, martialArt, category, difficulty, equipment, contactLevel, format]);
  const profile = useMemo(() => getArtProfile(selectedArt), [selectedArt]);
  const activeDrill = selectedDrill || results[0] || profile.drills[0];

  const resetFilters = () => { setQuery(''); setMartialArt(''); setCategory(''); setDifficulty(''); setEquipment(''); setContactLevel(''); setFormat(''); };

  return <main>
    <section className="hero">
      <div className="hero-copy">
        <p className="eyebrow"><Swords size={16}/> CombatAtlas live build</p>
        <h1>Searchable martial arts drills for every training path.</h1>
        <p className="lede">A full Vercel-ready drill atlas with <strong>{stats.drills}</strong> bundled drills across <strong>{stats.arts}</strong> martial arts. Search by technique, explore an art, filter by safety/contact/equipment, and plug in free data APIs later without breaking the app.</p>
        <div className="hero-actions"><a href="#search">Search drills</a><a href="#explore">Explore arts</a><a href="#sources">API readiness</a></div>
      </div>
      <div className="stat-grid">
        <div><Database/><strong>{stats.drills}</strong><span>seed drills</span></div>
        <div><Compass/><strong>{stats.arts}</strong><span>martial arts</span></div>
        <div><ShieldCheck/><strong>{stats.beginner}</strong><span>beginner-safe entries</span></div>
        <div><Dumbbell/><strong>{stats.noEquipment}</strong><span>no-equipment options</span></div>
      </div>
    </section>

    <section id="search" className="panel search-panel">
      <div className="section-head"><div><p className="eyebrow"><Search size={15}/> Drill search</p><h2>Find a drill by art, goal, skill, gear, or safety profile.</h2></div><button onClick={resetFilters}>Reset filters</button></div>
      <div className="filters">
        <label className="searchbox"><Search size={18}/><input value={query} onChange={(e)=>setQuery(e.target.value)} placeholder="Try armbar, teep, footwork, weapon, no equipment..." /></label>
        <select value={martialArt} onChange={(e)=>setMartialArt(e.target.value)}><option value="">All martial arts</option>{martialArts.map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select>
        <select value={category} onChange={(e)=>setCategory(e.target.value)}><option value="">All categories</option>{categories.map(c=><option key={c.id} value={c.id}>{c.label}</option>)}</select>
        <select value={difficulty} onChange={(e)=>setDifficulty(e.target.value)}><option value="">Any difficulty</option>{difficulties.map(v=><option key={v}>{v}</option>)}</select>
        <select value={equipment} onChange={(e)=>setEquipment(e.target.value)}><option value="">Any equipment</option>{equipmentOptions.slice(0,18).map(v=><option key={v}>{v}</option>)}</select>
        <select value={contactLevel} onChange={(e)=>setContactLevel(e.target.value)}><option value="">Any contact</option>{contactLevels.map(v=><option key={v}>{v}</option>)}</select>
        <select value={format} onChange={(e)=>setFormat(e.target.value)}><option value="">Any format</option>{formats.map(v=><option key={v}>{v}</option>)}</select>
      </div>
      <p className="result-count"><Filter size={16}/> Showing {results.length} of {searchDrills({ query, martialArt, category, difficulty, equipment, contactLevel, format }).length} matching drills.</p>
      <div className="results-layout">
        <div className="drill-list">{results.map(d => <button key={d.id} className={`drill-row ${activeDrill?.id===d.id?'active':''}`} onClick={()=>setSelectedDrill(d)}><strong>{d.title}</strong><span>{d.categoryLabel} • {d.difficulty} • {d.contactLevel}</span></button>)}</div>
        {activeDrill && <DrillDetail drill={activeDrill}/>}      
      </div>
    </section>

    <section id="explore" className="panel">
      <div className="section-head"><div><p className="eyebrow"><Compass size={15}/> Explore a martial art</p><h2>Browse one art like a syllabus, then jump into matching drills.</h2></div></div>
      <div className="art-tabs">{martialArts.map(a=><button key={a.id} className={selectedArt===a.id?'active':''} onClick={()=>setSelectedArt(a.id)}>{a.name}</button>)}</div>
      <div className="profile-card">
